// ===== MONTAR BUSCA =====
// Define o que será buscado no Gmail. Dois caminhos chegam aqui:
//  - Schedule Trigger (diário): últimos 3 dias
//  - Webhook (backfill manual): ?dias=90  ou  ?inicio=2026/07/01&fim=2026/10/16
// Não usa rótulo: os emails já vistos são controlados pela lista "vistos" do nó seguinte.

// ====== CONFIGURAÇÃO ======
const DIAS_DIARIO = 3;
const DIAS_BACKFILL_PADRAO = 90;
// Etiqueta do Gmail onde já caem seus emails de trabalho (filtro seu). Rede de segurança extra: tudo com essa etiqueta entra na busca.
// Deixe '' para desligar.
const ETIQUETA_TRABALHO = 'Trabalho';
// Plataformas e empresas que mandam resposta de candidatura.
// (LinkedIn fica de fora: os alertas de vagas dele são pesados e já são tratados pelo outro workflow;
//  as confirmações dele entram pelo assunto 'candidatura' na rede de segurança abaixo)
const REMETENTES = [
  'solides.com', 'gupy.com.br', 'ses-mail.inhire.app', 'mindsight.com.br', 'mg.mindsight.com.br',
  'indeedapply@indeed.com', 'pandape.com.br',
  'vagas.com.br', 'catho.com.br', 'kenoby.com', 'greenhouse.io', 'lever.co'
];
// Rede de segurança: qualquer remetente cujo assunto fale de candidatura
const ASSUNTOS = ['candidatura', '"processo seletivo"', '"próxima etapa"', 'entrevista', '"recebemos sua inscrição"', '"currículo recebido"',
  'feedback', 'retorno', '"sua participação"', '"programa de estágio"', 'trainee'];
// Remetentes que nunca interessam (alertas de vagas já são tratados pelo outro workflow)
const IGNORAR = [
  'noreply-accounts@google.com', 'inbound.gupy.com.br', 'jobalerts-noreply@linkedin.com',
  'noreply@glassdoor.com', 'donotreply@jobalert.indeed.com', 'donotreply@match.indeed.com',
  'newsletters-noreply@linkedin.com', 'invitations@linkedin.com', 'messages-noreply@linkedin.com', 'notifications-noreply@linkedin.com'
];
// ==========================

const entrada = $input.first().json || {};
const query = entrada.query || {};
const veioDoWebhook = !!(entrada.query || entrada.headers);

let periodo = `newer_than:${DIAS_DIARIO}d`;
let modo = 'diario';
if (veioDoWebhook) {
  modo = 'backfill';
  const ok = (d) => /^\d{4}\/\d{2}\/\d{2}$/.test(d || '');
  if (ok(query.inicio) || ok(query.fim)) {
    periodo = [ok(query.inicio) ? `after:${query.inicio}` : '', ok(query.fim) ? `before:${query.fim}` : ''].filter(Boolean).join(' ');
  } else {
    const dias = Math.min(Math.max(parseInt(query.dias, 10) || DIAS_BACKFILL_PADRAO, 1), 400);
    periodo = `newer_than:${dias}d`;
  }
}

const porEtiqueta = ETIQUETA_TRABALHO ? ` OR label:"${ETIQUETA_TRABALHO}"` : '';
// Do LinkedIn (jobs-noreply) só interessam os emails de candidatura; os alertas de vagas são pesados e ficam com o outro workflow.
const q = `(from:(${REMETENTES.join(' OR ')}) OR subject:(${ASSUNTOS.join(' OR ')})${porEtiqueta}) -from:(${IGNORAR.join(' OR ')}) -in:sent -label:vagas-processado -(from:jobs-noreply@linkedin.com -subject:candidatura) ${periodo}`;
return [{ json: { q, modo, periodo } }];

