// ===== CLASSIFICAR EMAILS DE CANDIDATURA =====
// Recebe os emails do Gmail e decide, só com regras (sem IA), de que tipo é cada um:
// confirmacao | visualizada | etapa | entrevista | oferta | recusa | cancelamento | outro | ruido
// A IA entra depois apenas para extrair empresa, vaga e prazo.

// ====== CONFIGURAÇÃO ======
const LIMITE_POR_RODADA = 100;   // máximo de emails analisados pela IA por execução
const LIMITE_TESTE = 5;          // no teste manual só processa 5
const MAX_VISTOS = 4000;         // quantos IDs de email lembrar
const TEXTO_MAX = 1500;          // quanto do corpo vai para a IA
const PLATAFORMAS = [
  ['solides.com', 'Solides'], ['gupy.com.br', 'Gupy'], ['inhire.app', 'Inhire'], ['mindsight.com.br', 'Mindsight'],
  ['indeed.com', 'Indeed'], ['linkedin.com', 'LinkedIn'], ['pandape.com.br', 'Pandapé'], 
  ['vagas.com.br', 'Vagas.com'], ['catho.com.br', 'Catho'], ['kenoby.com', 'Kenoby'], ['greenhouse.io', 'Greenhouse'], ['lever.co', 'Lever']
];
// ==========================

const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const decode = (s) => s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
function htmlParaTexto(html) {
  return decode((html || '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h\d|table|td)>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n');
}
const limpaCorpo = (t) => t
  .replace(/\[([^\]]*)\]\(https?:[^)]*\)/g, '$1')   // links em markdown
  .replace(/https?:\/\/\S+/g, '')                    // urls soltas
  .replace(/[\u034f\u00ad\u200b-\u200d]/g, '')                 // caracteres invisíveis
  .replace(/\s+/g, ' ').trim();

const RUIDO = /codigo de confirmacao|redefinicao de senha|recuperacao de senha|cadastramento de curriculo|foram reaproveitados|compartilhou alguns dados|confirme seu (e-?mail|cadastro)|boletim|newsletter|extrato mensal|ative sua conta|bem[- ]vindo ao site|finalizado com sucesso|recebemos suas respostas/;
const RE_CANCEL = /(candidatura|inscricao) (foi )?cancelad|cancelamento de candidatura/;
const RE_RECUSA = /optamos por (nao )?seguir|nao (seguiremos|vamos seguir|sera possivel seguir|foi selecionad|avancou|avancara)|nao atende(u)? ao perfil|infelizmente|outro (perfil|candidato)|encerr(amos|ado|ou) (o )?(seu )?processo|agradecimento de participacao|processo seletivo (foi )?encerrado/;
const RE_OFERTA = /(voce foi|foi) (aprovad|selecionad)[oa]|proposta de (emprego|trabalho|estagio)|carta[- ]oferta|oferta de (emprego|trabalho|estagio)|gostariamos de (te |lhe )?(contratar|ter voce)|parabens[^.]{0,40}(aprovad|contratad)/;
const RE_ENTREVISTA_ASSUNTO = /entrevista/;
const RE_ENTREVISTA_CORPO = /(entrevista (com|online|virtual|agendada|marcada)|agende (sua|a) entrevista|convite para (a |uma )?entrevista|convidamos (voce )?para (uma )?(entrevista|conversa)|agendamento de entrevista|sua entrevista|link da (entrevista|reuniao))/;
const RE_ETAPA_ASSUNTO = /proxima etapa|teste|desafio|case tecnico|fit cultural|avaliacao|mapeamento|dinamica|prova online/;
const RE_ETAPA_CORPO = /(realize|responda|acesse|inicie|iniciar|faca) (o|seu|sua|os) (teste|desafio|avaliacao)|chegou a uma etapa|proxima etapa|voce (foi )?avancou para/;
const RE_CONFIRMA = /candidatura (foi )?(efetuada|enviada|recebida|confirmada|registrada)|recebemos (a |sua )?(sua )?(candidatura|inscricao|curriculo)|inscricao (confirmada|recebida)|confirmacao de candidatura|curriculo foi recebido|inscricao via indeed|obrigad[oa] pela sua (recente )?candidatura|mantenha-se informado sobre sua candidatura|participando do processo seletivo|candidatura (foi )?enviada a/;
const RE_VISUALIZADA = /(candidatura|perfil|curriculo) (foi )?(visualizad|vist[ao])|visualizou (sua|o seu) (candidatura|perfil)/;

function detectar(assunto, corpo) {
  const a = norm(assunto);
  const t = norm(assunto + ' \n ' + corpo.slice(0, 1800));
  if (RUIDO.test(t)) return 'ruido';
  if (RE_CANCEL.test(t)) return 'cancelamento';
  if (RE_RECUSA.test(t) || a.trim() === 'feedback') return 'recusa';
  if (RE_OFERTA.test(t)) return 'oferta';
  if (RE_ENTREVISTA_ASSUNTO.test(a) || RE_ENTREVISTA_CORPO.test(t)) return 'entrevista';
  if (RE_ETAPA_ASSUNTO.test(a) || RE_ETAPA_CORPO.test(t)) return 'etapa';
  if (RE_CONFIRMA.test(t)) return 'confirmacao';
  if (RE_VISUALIZADA.test(t)) return 'visualizada';
  return 'outro';
}

function origem(de) {
  const dom = (de.split('@')[1] || '').replace(/[>\s]/g, '');
  for (const [d, nome] of PLATAFORMAS) if (dom === d || dom.endsWith('.' + d)) return { plataforma: nome, dominio: dom };
  return { plataforma: 'Direto', dominio: dom };
}

const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || [];
sd.apps = sd.apps || {};
const vistos = new Set(sd.vistos);
const producao = $execution.mode === 'production';
let modo = 'diario';
try { modo = $('Montar busca').first().json.modo || 'diario'; } catch (e) {}

const run = { modo, inicio: new Date().toISOString(), lidos: 0, novos: 0, ignorados: 0, adiados: 0, porTipo: {}, confirmacoes: [], suprimidos: 0, alertas: 0, novasApps: 0 };

const candidatos = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.id && !j.text && !j.html) continue;     // item vazio (busca sem resultado)
  run.lidos++;
  if (vistos.has(j.id)) continue;
  const de = (typeof j.from === 'string' ? j.from : (j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || '').toLowerCase();
  const assunto = (j.subject || '').toString();
  const ehIndeed = /@([a-z0-9-]+\.)*indeed\.com/.test(de);   // no Indeed o nome da empresa só vem no HTML, não no texto simples
  const corpoBruto = (!ehIndeed && j.text && j.text.length > 40) ? j.text : (htmlParaTexto(j.html || '') || j.text || '');
  const corpo = limpaCorpo(corpoBruto);
  const tipo = detectar(assunto, corpo);
  const data = j.date || (j.internalDate ? new Date(Number(j.internalDate)).toISOString() : new Date().toISOString());
  if (tipo === 'ruido') { run.ignorados++; sd.vistos.push(j.id); continue; }
  const { plataforma, dominio } = origem(de);
  // dica por regra (plano B se a IA falhar): Indeed escreve "Os seguintes itens foram enviados para <Empresa>. Boa sorte"
  let dicaEmpresa = '';
  const mi = corpo.match(/enviados? para\s+(.{2,80}?)\.\s*(?:boa sorte|$)/i);
  if (ehIndeed && mi) dicaEmpresa = mi[1].trim();
  candidatos.push({
    emailId: j.id, threadId: j.threadId || j.id, remetente: de, dominio, plataforma,
    assunto: assunto.replace(/\s+/g, ' ').trim(), data: new Date(data).toISOString(), tipoRegex: tipo,
    dicaEmpresa,
    texto: corpo.slice(0, TEXTO_MAX),
    link: `https://mail.google.com/mail/u/0/#all/${j.threadId || j.id}`
  });
}

// mais recentes primeiro para escolher quem entra na rodada; depois processa do mais antigo ao mais novo
candidatos.sort((a, b) => b.data.localeCompare(a.data));
const limite = producao ? LIMITE_POR_RODADA : LIMITE_TESTE;
run.adiados = Math.max(0, candidatos.length - limite);
const escolhidos = candidatos.slice(0, limite).sort((a, b) => a.data.localeCompare(b.data));
run.novos = escolhidos.length;

sd.run = run;
if (!escolhidos.length) return [{ json: { _vazio: true } }];
return escolhidos.map(c => ({ json: c }));

// ===== ATUALIZAR PAINEL =====
// Junta o que as regras decidiram (tipo do email) com o que a IA extraiu (empresa, vaga, prazo),
// atualiza o status da candidatura e decide se vale avisar no Telegram.
// Roda uma vez por email (modo "Run once for each item").

// ====== CONFIGURAÇÃO ======
const MAX_VISTOS = 4000;
const DIAS_ALERTA_RECENTE = 3;    // emails mais antigos que isso não geram alerta individual (entram só no resumo)
const PAINEL_URL = 'http://localhost:5678/webhook/candidaturas';
// ==========================

const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const limpa = (s) => (s == null ? '' : s).toString().replace(/[*_`\[\]]/g, '').replace(/\s+/g, ' ').trim();
const TIPOS = ['confirmacao', 'visualizada', 'etapa', 'entrevista', 'oferta', 'recusa', 'cancelamento'];
const STATUS_DO_TIPO = { confirmacao: 'enviada', visualizada: 'em_analise', etapa: 'etapa', entrevista: 'entrevista', oferta: 'oferta', recusa: 'recusada', cancelamento: 'cancelada' };
const RANK = { enviada: 1, em_analise: 2, etapa: 3, entrevista: 4, oferta: 5, recusada: 9, cancelada: 9 };
const TERMINAL = new Set(['recusada', 'cancelada']);
const ALERTAS = {
  entrevista: '🗓️ *CONVITE PARA ENTREVISTA*',
  etapa: '📝 *PRÓXIMA ETAPA / TESTE*',
  oferta: '🎉 *PROPOSTA / APROVAÇÃO*',
  recusa: '❌ *NÃO SEGUIRAM COM A CANDIDATURA*',
  cancelamento: '🚫 *CANDIDATURA CANCELADA*'
};
const NOME_PLATAFORMA = /^(gupy|solides|inhire|mindsight|indeed|linkedin|pandape|vagas\.?com|catho|kenoby|greenhouse|lever|sólides)$/;

const j = $('Loop Over Items').item.json;
const sd = $getWorkflowStaticData('global');
sd.apps = sd.apps || {}; sd.vistos = sd.vistos || [];
sd.run = sd.run || { porTipo: {}, confirmacoes: [], suprimidos: 0, alertas: 0, novasApps: 0, ignorados: 0 };
const run = sd.run;

// 1. Resposta da IA (tolerante a aspas soltas / vírgula sobrando)
let raw = ($json.text || '').replace(/```json/gi, '').replace(/```/g, '').trim();
const i0 = raw.indexOf('{'), i1 = raw.lastIndexOf('}');
if (i0 !== -1 && i1 > i0) raw = raw.slice(i0, i1 + 1);
const tenta = (t) => { try { return JSON.parse(t); } catch (e) { return null; } };
function salvar(t) {
  const o = tenta(t) || tenta(t.replace(/[“”]/g, '"').replace(/,\s*([}\]])/g, '$1'));
  if (o) return o;
  const str = (k) => { const m = t.match(new RegExp('"' + k + '"\\s*:\\s*"([^"]*)"')); return m ? m[1] : ''; };
  if (!str('empresa') && !str('vaga') && !str('tipo_sugerido')) return null;
  return { empresa: str('empresa'), vaga: str('vaga'), prazo: str('prazo'), tipo_sugerido: str('tipo_sugerido'), motivo: str('motivo') };
}
const ai = salvar(raw) || {};
const erroIA = !Object.keys(ai).length;

// 2. Empresa e vaga (com plano B quando a IA falha ou devolve o nome da plataforma)
const nomeDoDominio = () => {
  const partes = (j.dominio || '').split('.').filter(Boolean);
  const base = partes.length > 2 && ['com', 'net', 'org'].includes(partes[partes.length - 2]) ? partes[partes.length - 3] : (partes[partes.length - 2] || partes[0] || '');
  return base ? base.charAt(0).toUpperCase() + base.slice(1) : 'Empresa não identificada';
};
let empresa = limpa(ai.empresa);
if (!empresa || NOME_PLATAFORMA.test(norm(empresa)) || /^(null|n\/?a|desconhecid)/.test(norm(empresa))) {
  empresa = j.dicaEmpresa ? j.dicaEmpresa : (j.plataforma === 'Direto' ? nomeDoDominio() : 'Empresa não identificada');
}
let vaga = limpa(ai.vaga);
if (/^(null|n\/?a)$/i.test(vaga)) vaga = '';
// plano B: só aproveita o assunto quando ele tem formato conhecido (Indeed / Solides); senão deixa em branco
if (!vaga) { const m = (j.assunto || '').match(/^(?:inscri[çc][ãa]o via indeed:|candidatura efetuada em)\s*(.+)$/i); if (m) vaga = limpa(m[1]).slice(0, 120); }
const nomeVaga = (a) => a.vaga || 'Vaga não informada';
const prazo = /^(null|n\/?a)?$/i.test(limpa(ai.prazo)) ? '' : limpa(ai.prazo);
const motivo = limpa(ai.motivo).slice(0, 200);

// 3. Tipo final: as regras mandam; a IA só desempata quando as regras não reconheceram
let tipo = j.tipoRegex;
if (tipo === 'outro') { const s = norm(ai.tipo_sugerido); tipo = TIPOS.includes(s) ? s : 'outro'; }

const marcarVisto = () => { sd.vistos.push(j.emailId); if (sd.vistos.length > MAX_VISTOS) sd.vistos = sd.vistos.slice(-MAX_VISTOS); };

if (tipo === 'outro') {
  run.ignorados = (run.ignorados || 0) + 1;
  marcarVisto();
  return { json: { notificar: false, tipo, empresa, vaga, emailId: j.emailId, marcarLido: false } };
}

// 4. Acha (ou cria) a candidatura correspondente
const ek = norm(empresa).replace(/[^a-z0-9]/g, '');
const vk = norm(vaga).replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
let app = null, melhor = -1;
for (const a of Object.values(sd.apps)) {
  if (a.ek !== ek) continue;
  let pontos = 0;
  if (a.vk === vk) pontos = 3;
  else if (vk && a.vk && (a.vk.includes(vk) || vk.includes(a.vk))) pontos = 2;
  else if (!vk || !a.vk) pontos = 1;
  if (pontos > melhor) { melhor = pontos; app = a; }
}
const nova = !app;
if (nova) {
  app = { id: ek + '|' + vk, ek, vk, empresa, vaga, status: 'enviada', plataforma: j.plataforma, primeira: j.data, hist: [] };
  sd.apps[app.id] = app;
  run.novasApps = (run.novasApps || 0) + 1;
}
if (vaga.length > (app.vaga || '').length && !nova) { app.vaga = vaga; }   // guarda o nome mais completo
if (empresa !== 'Empresa não identificada' && app.empresa === 'Empresa não identificada') app.empresa = empresa;

// 5. Atualiza o status (nunca volta atrás; recusa/cancelamento encerram)
const novoStatus = STATUS_DO_TIPO[tipo];
const statusAntes = app.status;
let mudou = false;
if (TERMINAL.has(app.status) && !TERMINAL.has(novoStatus)) {
  // candidatura já encerrada: ignora emails posteriores que não sejam de encerramento
} else if (TERMINAL.has(novoStatus) || RANK[novoStatus] >= RANK[app.status]) {
  mudou = novoStatus !== app.status || tipo === 'etapa' || tipo === 'entrevista';
  app.status = novoStatus;
}
app.ultima = j.data; app.link = j.link; app.plataforma = j.plataforma;
if (prazo && (tipo === 'etapa' || tipo === 'entrevista')) app.prazo = prazo;
if (motivo && (tipo === 'recusa' || tipo === 'cancelamento' || tipo === 'etapa' || tipo === 'oferta')) app.motivo = motivo;
app.hist.push({ data: j.data, tipo, assunto: (j.assunto || '').slice(0, 90) });
if (app.hist.length > 12) app.hist = app.hist.slice(-12);
marcarVisto();

// 6. Contagem para o resumo
run.porTipo[tipo] = (run.porTipo[tipo] || 0) + 1;
if (tipo === 'confirmacao' && nova) { run.confirmacoes = run.confirmacoes || []; if (run.confirmacoes.length < 40) run.confirmacoes.push(`${app.empresa} — ${nomeVaga(app)}`.slice(0, 90)); }

// 7. Decide se avisa agora
const idadeDias = (Date.now() - new Date(j.data).getTime()) / 86400000;
const alertavel = !!ALERTAS[tipo];
const aviso = alertavel && mudou && idadeDias <= DIAS_ALERTA_RECENTE;
if (alertavel && mudou && !aviso) run.suprimidos = (run.suprimidos || 0) + 1;
// marcar como lido só o que não pede ação (confirmação / visualizada); o resto fica em negrito para você abrir
const marcarLido = ['confirmacao', 'visualizada'].includes(tipo);
if (!aviso) return { json: { notificar: false, tipo, empresa: app.empresa, vaga: nomeVaga(app), emailId: j.emailId, marcarLido } };

run.alertas = (run.alertas || 0) + 1;
let texto = `${ALERTAS[tipo]}\n🏢 *Empresa:* ${app.empresa}\n📌 *Vaga:* ${nomeVaga(app)}\n📨 *Via:* ${j.plataforma}`;
if (prazo && (tipo === 'etapa' || tipo === 'entrevista')) texto += `\n⏰ *Prazo/Data:* ${prazo}`;
if (motivo) texto += `\n💬 ${motivo}`;
if (erroIA) texto += `\n\nℹ️ A IA não conseguiu ler o email; empresa e vaga podem estar incompletas.`;
texto += `\n\n📧 [Abrir o email](${j.link})\n🗂 [Painel de candidaturas](${PAINEL_URL})`;
return { json: { notificar: true, texto, tipo, empresa: app.empresa, vaga: nomeVaga(app), emailId: j.emailId, marcarLido } };

// ===== RESUMO DA RODADA =====
// Mensagem única no fim: confirmações novas, alertas e o total do painel.
// Em execução diária sem novidade não manda nada (retorna lista vazia).
const sd = $getWorkflowStaticData('global');
const run = sd.run || {};
const apps = Object.values(sd.apps || {});
const t = run.porTipo || {};
const backfill = run.modo === 'backfill';
const teveNovidade = (run.novasApps || 0) > 0 || (run.alertas || 0) > 0 || (run.suprimidos || 0) > 0 || Object.keys(t).length > 0;
if (!backfill && !teveNovidade) return [];

const PAINEL_URL = 'http://localhost:5678/webhook/candidaturas';
const cont = (s) => apps.filter(a => a.status === s).length;
let m = backfill ? '📦 *Candidaturas — carga inicial*\n' : '📋 *Candidaturas — resumo*\n';
m += `📧 Emails lidos: ${run.lidos || 0} · analisados: ${run.novos || 0}`;
if (run.adiados) m += ` · adiados: ${run.adiados}`;
m += '\n';
if (run.novasApps) m += `🆕 Candidaturas novas no painel: ${run.novasApps}\n`;
const linhas = [];
if (t.entrevista) linhas.push(`🗓️ entrevistas: ${t.entrevista}`);
if (t.etapa) linhas.push(`📝 etapas/testes: ${t.etapa}`);
if (t.oferta) linhas.push(`🎉 propostas: ${t.oferta}`);
if (t.recusa) linhas.push(`❌ recusas: ${t.recusa}`);
if (t.cancelamento) linhas.push(`🚫 cancelamentos: ${t.cancelamento}`);
if (linhas.length) m += linhas.join(' · ') + '\n';
if (run.suprimidos) m += `(${run.suprimidos} resposta(s) antiga(s) entraram no painel sem alerta individual)\n`;
const conf = (run.confirmacoes || []).slice(0, 8);
if (conf.length) {
  m += `\n✅ *Confirmadas:*\n` + conf.map(c => `• ${c.replace(/[*_`\[\]]/g, '')}`).join('\n');
  if ((run.confirmacoes || []).length > conf.length) m += `\n• … e mais ${(run.confirmacoes || []).length - conf.length}`;
  m += '\n';
}
m += `\n🗂 *Painel:* ${apps.length} candidaturas · ${cont('enviada') + cont('em_analise')} aguardando · ${cont('etapa') + cont('entrevista')} em andamento · ${cont('recusada') + cont('cancelada')} encerradas\n${PAINEL_URL}`;
return [{ json: { texto: m } }];

// ===== UTILITÁRIO (uso único): lista os emails que o robô já processou =====
// Só existe memória em execução de verdade (link /webhook/, sem "-test").
const sd = $getWorkflowStaticData('global');
const ids = [...new Set(sd.vistos || [])];
if (!ids.length) return [{ json: { messageId: '', vazio: true } }];
return ids.map(id => ({ json: { messageId: id } }));

const itens = $input.all().filter(i => i.json && !i.json.error);
const total = $('Listar IDs vistos').all().filter(i => i.json.messageId).length;
const erros = $input.all().length - itens.length;
return [{ json: { texto: `🏷 *Etiquetas aplicadas no histórico*\nEmails já processados: ${total}\nComo etiqueta: Trabalho + Candidaturas${erros ? `\n⚠️ Falhas: ${erros}` : ''}` } }];

// ===== PAINEL DE CANDIDATURAS (página HTML) =====
// Abre em http://localhost:5678/webhook/candidaturas
const sd = $getWorkflowStaticData('global');
const apps = Object.values(sd.apps || {});
const esc = (s) => (s == null ? '' : String(s)).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const ROTULO = { enviada: 'Enviada', em_analise: 'Em análise', etapa: 'Etapa / teste', entrevista: 'Entrevista', oferta: 'Proposta', recusada: 'Recusada', cancelada: 'Cancelada' };
const ORDEM = { entrevista: 0, oferta: 1, etapa: 2, em_analise: 3, enviada: 4, recusada: 5, cancelada: 6 };
const fmt = (iso) => { try { return new Date(iso).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' }); } catch (e) { return ''; } };

apps.sort((a, b) => (ORDEM[a.status] - ORDEM[b.status]) || String(b.ultima).localeCompare(String(a.ultima)));
const total = apps.length;
const n = (s) => apps.filter(a => a.status === s).length;
const chips = Object.keys(ROTULO).map(s => `<span class="chip ${s}">${ROTULO[s]} <b>${n(s)}</b></span>`).join('');
const linhas = apps.map(a => `<tr>
<td><b>${esc(a.empresa)}</b></td><td>${esc(a.vaga || 'Vaga não informada')}</td>
<td><span class="chip ${esc(a.status)}">${ROTULO[a.status] || esc(a.status)}</span>${a.prazo ? `<div class="sub">⏰ ${esc(a.prazo)}</div>` : ''}${a.motivo ? `<div class="sub">${esc(a.motivo)}</div>` : ''}</td>
<td>${esc(a.plataforma)}</td><td>${fmt(a.primeira)}</td><td>${fmt(a.ultima)}</td>
<td>${a.link ? `<a href="${esc(a.link)}" target="_blank" rel="noopener">email</a>` : ''}</td></tr>`).join('');

const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Painel de candidaturas</title>
<style>
:root{--bg:#fff;--fg:#1c1b1a;--mut:#6b6762;--line:#e4e1dc;--card:#faf9f7}
@media(prefers-color-scheme:dark){:root{--bg:#161514;--fg:#ecebe8;--mut:#9a958d;--line:#2d2b28;--card:#1e1d1b}}
body{margin:0;padding:24px 16px;background:var(--bg);color:var(--fg);font:15px/1.45 system-ui,sans-serif}
main{max-width:1100px;margin:0 auto}h1{font-size:22px;margin:0 0 4px}.mut{color:var(--mut);margin:0 0 16px}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}
.chip{display:inline-block;padding:2px 10px;border-radius:999px;font-size:13px;border:1px solid var(--line);background:var(--card);white-space:nowrap}
.chip.entrevista,.chip.oferta{background:#1f7a4d;color:#fff;border-color:#1f7a4d}.chip.etapa{background:#b8860b;color:#fff;border-color:#b8860b}
.chip.recusada,.chip.cancelada{color:var(--mut);text-decoration:line-through}
.wrap{overflow-x:auto;border:1px solid var(--line);border-radius:10px}table{border-collapse:collapse;width:100%;min-width:760px}
th,td{padding:10px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--mut);background:var(--card)}
tr:last-child td{border-bottom:0}.sub{font-size:12px;color:var(--mut);margin-top:3px;max-width:260px}a{color:inherit}
</style></head><body><main>
<h1>Painel de candidaturas</h1><p class="mut">${total} candidatura${total === 1 ? '' : 's'} · atualizado pelo workflow a cada execução</p>
<div class="chips">${chips}</div>
<div class="wrap"><table><thead><tr><th>Empresa</th><th>Vaga</th><th>Status</th><th>Via</th><th>Início</th><th>Última</th><th></th></tr></thead>
<tbody>${linhas || '<tr><td colspan="7">Nenhuma candidatura registrada ainda. Rode o backfill: /webhook/candidaturas-backfill?dias=90</td></tr>'}</tbody></table></div>
</main></body></html>`;
return [{ json: { html } }];
